-- =====================================================================
--  LIFEANGLE — rechten voor de API herstellen
--
--  Geen migratie. Draai dit één keer in de SQL-editor als de app overal
--  403 krijgt ("permission denied") of als "Klaar" bij de onboarding 409
--  geeft. Opnieuw draaien kan geen kwaad.
--
--  WAAROM  Nieuwere Supabase-projecten zetten nieuwe tabellen niet meer
--          automatisch open voor de API (instelling in Data API). Dan
--          heeft de rol "authenticated" geen rechten op de tabellen die de
--          migraties maakten, en weigert de database elke vraag van een
--          ingelogde gebruiker. RLS beschermt de rijen; dit zijn de rechten
--          op tabelniveau die Supabase normaal zelf geeft.
--
--  WAT     1. authenticated en service_role: precies de rechten van een
--             standaard Supabase-project na alle migraties (01 t/m 87),
--             zoals getest. Ingetrokken rechten blijven ingetrokken.
--          2. anon (niet ingelogd): geen tabellen; alleen de prijspagina
--             en de diagnose. Zoals 69 bedoelde.
--          3. Profielen die ontbreken voor bestaande gebruikers worden
--             aangemaakt (zonder profiel kan je geen huishouden maken).
--          4. Nieuwe tabellen en functies krijgen voortaan dezelfde
--             standaardrechten voor authenticated en service_role.
--
--  Gegenereerd uit een database met alle migraties. Objecten die bij jou
--  niet bestaan, worden overgeslagen.
-- =====================================================================

grant usage on schema public to anon, authenticated, service_role;

-- 1. authenticated en service_role -------------------------------------
do $g$ begin if to_regclass('public.activity') is not null then grant DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE on table public.activity to authenticated; end if; end $g$;
