-- 2. anon: alleen wat bewust openbaar is ---------------------------------
do $g$ begin if to_regprocedure('public.publieke_prijzen()') is not null then grant execute on function public.publieke_prijzen() to anon; end if; end $g$;
do $g$ begin if to_regprocedure('public.debug_auth_uid()') is not null then grant execute on function public.debug_auth_uid() to anon; end if; end $g$;

-- 3. ontbrekende profielen ------------------------------------------------
insert into public.profile (id, full_name)
select u.id, coalesce(u.raw_user_meta_data ->> 'full_name', u.email)
from auth.users u
where not exists (select 1 from public.profile p where p.id = u.id)
on conflict (id) do nothing;

-- 4. standaardrechten voor wat later nog bijkomt -------------------------
alter default privileges in schema public grant select, insert, update, delete on tables to authenticated, service_role;
alter default privileges in schema public grant usage, select on sequences to authenticated, service_role;
alter default privileges in schema public grant execute on functions to authenticated, service_role;

-- Controle ---------------------------------------------------------------
select 'ingelogd mag household lezen' as controle,
       has_table_privilege('authenticated', 'public.household', 'select')::text as resultaat
union all select 'ingelogd mag my_households()',
       has_function_privilege('authenticated', 'public.my_households()', 'execute')::text
union all select 'gebruikers zonder profiel',
       (select count(*) from auth.users u where not exists (select 1 from public.profile p where p.id = u.id))::text
union all select 'trigger voor nieuwe profielen',
       (select count(*) from pg_trigger where tgname = 'on_auth_user_created')::text;
-- Verwacht: true, true, 0, 1
